/** A destination in the bundled manuscript, with a page fallback for PDF viewers. */
export interface PaperReference {
  /** Hyperref destination embedded in the particular bundled PDF. */
  destination: string;
  /** Physical PDF page; update this along with the destination when replacing the PDF. */
  page: number;
  label: { en: string; de: string };
}

