/** Construct a GitHub Pages-compatible URL to the bundled manuscript and destination. */
export function paperReferenceUrl(
  reference: PaperReference,
  target: "destination" | "page",
): string {
  const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
  const fragment =
    target === "destination"
      ? `nameddest=${encodeURIComponent(reference.destination)}`
      : `page=${reference.page}`;

  return `${basePath}/research/manuscript.pdf#${fragment}`;
}
